'use client';

import * as React from 'react';
import { Tooltip } from '@base-ui/react/tooltip';
import './status.css';

/* LED and STATUS BADGE (KAMUI-16).
 * An LED says one state by colour and never alone: it sits beside words (a badge, a readout, an engraving).
 * The badge is not pressable; its hint (the command that fixes it) shows as a tooltip on hover and focus. */

export type LedKind = 'live' | 'waiting' | 'failed' | 'link' | 'off';

export interface LedProps extends React.HTMLAttributes<HTMLSpanElement> {
  kind: LedKind;
  /** 5 (default) or 4 (small). */
  size?: 'default' | 'small';
}

/** A tiny lamp, lit from the top left. Decorative: pair it with words. */
export function Led({ kind, size = 'default', className, ...props }: LedProps) {
  return <span aria-hidden data-kind={kind} data-size={size} className={className ? `mu-led ${className}` : 'mu-led'} {...props} />;
}

export interface StatusBadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  led: LedKind;
  /** The state, short, uppercase in the label role: "JEV LIVE", "JEV OFFLINE · ADD KEY TO KEYCHAIN". */
  children: React.ReactNode;
  /** What fixes it, shown on hover and focus: "security add-generic-password -s kamui-jev …". */
  hint?: string;
}

/** A state the system is in, with its LED. Not a button. */
export const StatusBadge = React.forwardRef<HTMLSpanElement, StatusBadgeProps>(function StatusBadge({ led, children, hint, className, ...props }, ref) {
  const badge = (
    <span ref={ref} role="status" tabIndex={hint ? 0 : undefined} className={['mu-badge', 'mu-type-label', className].filter(Boolean).join(' ')} {...props}>
      <Led kind={led} />
      {children}
    </span>
  );
  if (!hint) return badge;
  return (
    <Tooltip.Root>
      <Tooltip.Trigger render={badge} aria-description={hint} />
      <Tooltip.Portal>
        <Tooltip.Positioner side="bottom" sideOffset={8} collisionPadding={8}>
          <Tooltip.Popup className="mu-provenance mu-type-readout" style={{ textTransform: 'none' }}>{hint}</Tooltip.Popup>
        </Tooltip.Positioner>
      </Tooltip.Portal>
    </Tooltip.Root>
  );
});

@import "../tokens.css";
@import "../provenance-tooltip/provenance-tooltip.css";

/* LED and status badge (the reference design's .led-*, .pill.status). Its look is the status recipe (--mu-r-status-*). */
.mu-led {
  display: inline-block;
  flex: none;
  width: var(--mu-r-status-led-size);
  height: var(--mu-r-status-led-size);
  border-radius: var(--mu-round);
  box-shadow: var(--mu-r-status-led-shadow);
}
.mu-led[data-size="small"] { width: var(--mu-r-status-led-size-small); height: var(--mu-r-status-led-size-small); }
.mu-led[data-kind="live"] { background: var(--mu-r-status-led-live-background); box-shadow: var(--mu-r-status-led-live-shadow); }
.mu-led[data-kind="waiting"] { background: var(--mu-r-status-led-waiting-background); }
.mu-led[data-kind="failed"] { background: var(--mu-r-status-led-failed-background); }
.mu-led[data-kind="link"] { background: var(--mu-r-status-led-link-background); }
.mu-led[data-kind="off"] { background: var(--mu-r-status-led-off-background); box-shadow: var(--mu-r-status-led-off-shadow); }

.mu-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--mu-r-status-badge-gap);
  height: var(--mu-r-status-badge-height);
  padding: var(--mu-zero) var(--mu-r-status-badge-pad);
  border-radius: var(--mu-radius-pill);
  white-space: nowrap;
  font: var(--mu-r-status-badge-font);
  letter-spacing: var(--mu-r-status-badge-tracking);
  text-transform: uppercase;
  color: var(--mu-ink2);
  background: var(--mu-r-status-badge-background);
  box-shadow: var(--mu-r-status-badge-shadow);
  cursor: default;
}
.mu-badge:focus-visible { outline: var(--mu-focus-width) solid var(--mu-focus); outline-offset: var(--mu-focus-offset); }
